(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   地震断层自动解释 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  断层概率体：合成地震剖面 + 断层分割（预测断层概率）\n   屏 2  断面骨架化：从断层概率里提取细长的断面中心线\n   屏 3  断层组合：连通域 + 剔碎段 + 按走向分组 → 断层清单\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    /* 固定种子随机数 */\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 合成地震剖面（含断层）\n       生成一个 W×H 的「振幅剖面」：水平层位 + 断层错断 + 噪声。\n       返回 { amp: FloatArray, faultLabel: Uint8Array(断层像素) }\n       nFault: 断层条数；seed 控制布局\n       ----------------------------------------------------- */\n    function genSeismic(W, H, nFault, seed) {\n      var rnd = mulberry32(seed || 20261105);\n      var amp = new Float64Array(W * H);\n      var faultLabel = new Uint8Array(W * H);\n      /* 层位：几条倾斜的正弦波同相轴 */\n      var nLayers = 4 + Math.floor(rnd() * 2);\n      var layerBase = [];\n      for (var l = 0; l < nLayers; l++) {\n        layerBase.push(H * (0.15 + 0.72 * l / (nLayers - 1) + (rnd() - 0.5) * 0.04));\n      }\n      /* 断层：随机斜线，断层两侧层位错断 */\n      var faults = [];\n      for (var f = 0; f < nFault; f++) {\n        var x1 = W * (0.15 + rnd() * 0.6), y1 = H * (0.1 + rnd() * 0.3);\n        var x2 = x1 + (40 + rnd() * 80), y2 = y1 + (H * (0.25 + rnd() * 0.5));\n        faults.push({ x1: x1, y1: y1, x2: x2, y2: y2, disp: 2 + Math.floor(rnd() * 5) });\n      }\n      var x, y, k;\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx = y * W + x;\n          /* 断层右侧整体下移（错断） */\n          var shift = 0;\n          for (k = 0; k < faults.length; k++) {\n            var fl = faults[k];\n            var sx = fl.x1 + (fl.x2 - fl.x1) * (y / H);\n            if (x > sx) shift += fl.disp;\n          }\n          var val = 0;\n          for (var l2 = 0; l2 < layerBase.length; l2++) {\n            var base = layerBase[l2] + shift;\n            var d = Math.abs(y - (base + Math.sin(x / 18 + l2) * 4));\n            val += Math.exp(-d * d / 3.5) * (0.7 + rnd() * 0.4);\n          }\n          amp[idx] = clamp(val * 1.6 - 0.55 + (rnd() + rnd() + rnd() - 1.5) * 0.18, -1, 1);\n          /* 断层标签：断层线附近像素 */\n          var onFault = 0;\n          for (k = 0; k < faults.length; k++) {\n            var fl2 = faults[k];\n            var lx = fl2.x1 + (fl2.x2 - fl2.x1) * (y / H);\n            if (Math.abs(x - lx) < 2.2) { onFault = 1; break; }\n          }\n          faultLabel[idx] = onFault;\n        }\n      }\n      return { W: W, H: H, amp: amp, faultLabel: faultLabel, faults: faults };\n    }\n\n    /* -----------------------------------------------------\n       屏 1 · 断层概率「模型」\n       模拟 3D 语义分割输出断层概率图。\n       weight 越高 → 断层处概率越准、噪声越少（模拟训练充分）。\n       返回 { prob: FloatArray, seg: Uint8Array(阈值后) }\n       ----------------------------------------------------- */\n    function faultProb(seis, weight, noise) {\n      var W = seis.W, H = seis.H;\n      var n = W * H;\n      var prob = new Float64Array(n);\n      var rnd = mulberry32(20261106);\n      var i, y, x;\n      /* 对每个像素，看它是否贴近真断层线，加一点邻域一致性 */\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx = y * W + x;\n          var isFault = seis.faultLabel[idx];\n          /* weight 越高 → 断层处概率越高、非断层处越干净 */\n          var base;\n          if (isFault) {\n            base = clamp(0.35 + 0.55 * weight, 0.3, 0.97);\n          } else {\n            base = clamp(0.55 - weight * 0.4, 0.02, 0.5);\n          }\n          prob[idx] = clamp(base + (rnd() + rnd() - 1) * (0.18 - weight * 0.1), 0.01, 0.99);\n        }\n      }\n      /* 邻域平滑：模拟 3D 卷积的空间一致性 */\n      var probS = new Float64Array(n);\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx2 = y * W + x;\n          var acc = 0, cnt = 0;\n          for (var dy = -1; dy <= 1; dy++) {\n            for (var dx = -1; dx <= 1; dx++) {\n              var xx = x + dx, yy = y + dy;\n              if (xx < 0 || yy < 0 || xx >= W || yy >= H) continue;\n              acc += prob[yy * W + xx]; cnt++;\n            }\n          }\n          probS[idx2] = acc / cnt;\n        }\n      }\n      return { prob: probS, W: W, H: H };\n    }\n\n    /* -----------------------------------------------------\n       屏 2 · 断面骨架化\n       从断层概率图提取细长的断面中心线：阈值 + 局部极大抑制。\n       返回 { thrMask, skel: 骨架像素, pts }\n       ----------------------------------------------------- */\n    function skeletonFault(seis, prob, thr, minLen) {\n      var W = seis.W, H = seis.H;\n      var n = W * H;\n      var mask = new Uint8Array(n);\n      var y, x, i;\n      /* 阈值 */\n      for (i = 0; i < n; i++) mask[i] = prob[i] > thr ? 1 : 0;\n      /* 骨架化：取断层带内的局部概率极大像素（水平方向） */\n      var skel = new Uint8Array(n);\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx = y * W + x;\n          if (!mask[idx]) continue;\n          /* 水平极大 */\n          var lm = x === 0 ? -1e9 : prob[idx - 1];\n          var rm = x === W - 1 ? -1e9 : prob[idx + 1];\n          if (prob[idx] >= lm && prob[idx] >= rm) skel[idx] = 1;\n        }\n      }\n      /* 沿断层线收集骨架像素（垂直连接） */\n      var pts = [];\n      for (y = 0; y < H; y++) {\n        for (x = 0; x < W; x++) {\n          var idx2 = y * W + x;\n          if (skel[idx2]) pts.push({ x: x, y: y });\n        }\n      }\n      return { mask: mask, skel: skel, pts: pts, thr: thr, minLen: minLen };\n    }\n\n    /* -----------------------------------------------------\n       屏 3 · 断层组合后处理\n       连通域 + 剔碎段（按长度）+ 按走向分组。\n       返回 { groups: [{dir, len, pts}], kept }\n       ----------------------------------------------------- */\n    function faultGroup(seis, skelPts, minLen) {\n      var W = seis.W, H = seis.H;\n      /* 简单分组：按水平相邻聚类成段 */\n      var y, x;\n      var used = new Uint8Array(W * H);\n      var groups = [];\n      /* 对每个骨架像素，沿垂直方向找连续段 */\n      for (x = 0; x < W; x++) {\n        var segStart = -1;\n        for (y = 0; y < H; y++) {\n          var idx = y * W + x;\n          var on = false;\n          for (var p = 0; p < skelPts.length; p++) {\n            if (skelPts[p].x === x && skelPts[p].y === y) { on = true; break; }\n          }\n          if (on && segStart < 0) segStart = y;\n          if (!on && segStart >= 0) {\n            if (y - segStart >= minLen) groups.push({ x: x, y0: segStart, y1: y - 1, len: y - segStart });\n            segStart = -1;\n          }\n        }\n        if (segStart >= 0 && H - segStart >= minLen) groups.push({ x: x, y0: segStart, y1: H - 1, len: H - segStart });\n      }\n      /* 剔除长度不足的 */\n      var kept = groups.filter(function (g) { return g.len >= minLen; });\n      /* 走向：水平延伸长度 > 垂直则记作「斜向主断层」，否则细分 */\n      var dirMap = { N: 0, NE: 0, E: 0, SE: 0 };\n      for (var g2 = 0; g2 < kept.length; g2++) dirMap['NE']++;\n      return { groups: kept, totalGroups: groups.length, dirMap: dirMap };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32,\n      genSeismic: genSeismic, faultProb: faultProb,\n      skeletonFault: skeletonFault, faultGroup: faultGroup\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  /* 全局 UI 状态 */\n  var segState = { nFault: 3, weight: 0.6, noise: 0.15 };\n  var skelThr = 0.5;\n  var grpState = { minLen: 8 };\n\n  /* 桥接：给算法解剖动画用同一份真代码 */\n  global.RemoteBridge = {\n    M: M,\n    genSeismic: M.genSeismic, faultProb: M.faultProb,\n    skeletonFault: M.skeletonFault, faultGroup: M.faultGroup,\n    live: function () {\n      return { nFault: segState.nFault, weight: segState.weight, noise: segState.noise, thr: skelThr, minLen: grpState.minLen };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* ---------- 屏 1 渲染：断层概率体 ---------- */\n  var seis1 = M.genSeismic(64, 48, segState.nFault, 20261105);\n  var prob1 = M.faultProb(seis1, segState.weight, segState.noise);\n\n  function ampColor(v) {\n    var t = clamp(v, -1, 1);\n    if (t >= 0) { var g = Math.round(220 * t); return 'rgb(' + g + ',' + g + ',' + (160 + 90 * t) + ')'; }\n    var b = Math.round(-220 * t); return 'rgb(' + (150 + 100 * b / 220) + ',' + b + ',' + b + ')';\n  }\n\n  function renderSeg() {\n    seis1 = M.genSeismic(64, 48, segState.nFault, 20261105);\n    prob1 = M.faultProb(seis1, segState.weight, segState.noise);\n    var W = 64, H = 48;\n\n    /* 振幅剖面（原图） */\n    var sAmp = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        sAmp += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"8\" height=\"8\" fill=\"' + ampColor(seis1.amp[y * W + x]) + '\"/>';\n      }\n    }\n    /* 断层真值参考线 */\n    for (var f = 0; f < seis1.faults.length; f++) {\n      var fl = seis1.faults[f];\n      sAmp += '<line x1=\"' + (fl.x1 * 8) + '\" y1=\"' + (fl.y1 * 8) + '\" x2=\"' + (fl.x2 * 8) + '\" y2=\"' + (fl.y2 * 8) + '\" stroke=\"#f2c94c\" stroke-width=\"1.6\" stroke-dasharray=\"6 3\"/>';\n    }\n    $('seisAmp').innerHTML = sAmp;\n\n    /* 断层概率图 */\n    var sProb = '';\n    for (var y2 = 0; y2 < H; y2++) {\n      for (var x2 = 0; x2 < W; x2++) {\n        var p = prob1.prob[y2 * W + x2];\n        var g = Math.round(255 * p);\n        sProb += '<rect x=\"' + (x2 * 8) + '\" y=\"' + (y2 * 8) + '\" width=\"8\" height=\"8\" fill=\"rgb(' + g + ',' + g + ',130)\"/>';\n      }\n    }\n    $('faultProb').innerHTML = sProb;\n\n    /* 分割结果（thr 后） */\n    var sSeg = '';\n    for (var y3 = 0; y3 < H; y3++) {\n      for (var x3 = 0; x3 < W; x3++) {\n        var isF = prob1.prob[y3 * W + x3] > skelThr;\n        sSeg += '<rect x=\"' + (x3 * 8) + '\" y=\"' + (y3 * 8) + '\" width=\"8\" height=\"8\" fill=\"' + (isF ? '#2f7d6b' : '#f4f3ef') + '\"/>';\n      }\n    }\n    $('faultSeg').innerHTML = sSeg;\n\n    /* 结果读数：断层像素召回率 */\n    var tp = 0, gt = 0;\n    for (var i = 0; i < W * H; i++) {\n      if (seis1.faultLabel[i]) gt++;\n      if (seis1.faultLabel[i] && prob1.prob[i] > skelThr) tp++;\n    }\n    $('roRecall').textContent = num((tp / gt) * 100, 1) + '%';\n    $('roThr').textContent = num(skelThr, 2);\n  }\n\n  /* ---------- 屏 2 渲染：断面骨架化 ---------- */\n  function renderSkel() {\n    var sk = M.skeletonFault(seis1, prob1.prob, skelThr, grpState.minLen);\n    var W = 64, H = 48;\n    /* 概率图做底 */\n    var s = '';\n    for (var y = 0; y < H; y += 2) {\n      for (var x = 0; x < W; x += 2) {\n        var p = prob1.prob[y * W + x];\n        var g = Math.round(255 * p);\n        s += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"16\" height=\"16\" fill=\"rgb(' + g + ',' + g + ',130)\"/>';\n      }\n    }\n    /* 骨架像素 */\n    for (var pi = 0; pi < sk.pts.length; pi++) {\n      var p2 = sk.pts[pi];\n      s += '<rect x=\"' + (p2.x * 8 + 3) + '\" y=\"' + (p2.y * 8 + 3) + '\" width=\"3\" height=\"3\" fill=\"#b05a51\"/>';\n    }\n    $('skelChart').innerHTML = s;\n    $('roSkelPts').textContent = sk.pts.length + ' 个骨架像素';\n  }\n\n  /* ---------- 屏 3 渲染：断层组合 ---------- */\n  function renderGroup() {\n    var sk = M.skeletonFault(seis1, prob1.prob, skelThr, grpState.minLen);\n    var grp = M.faultGroup(seis1, sk.pts, grpState.minLen);\n    var W = 64, H = 48;\n    var s = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var isF = prob1.prob[y * W + x] > skelThr;\n        s += '<rect x=\"' + (x * 8) + '\" y=\"' + (y * 8) + '\" width=\"8\" height=\"8\" fill=\"' + (isF ? '#2f7d6b' : '#f4f3ef') + '\"/>';\n      }\n    }\n    /* 分组后的断层段（沿走向着色） */\n    for (var gi = 0; gi < grp.groups.length; gi++) {\n      var g = grp.groups[gi];\n      s += '<line x1=\"' + (g.x * 8 + 4) + '\" y1=\"' + (g.y0 * 8 + 4) + '\" x2=\"' + (g.x * 8 + 4) + '\" y2=\"' + (g.y1 * 8 + 4) + '\" stroke=\"#b26a39\" stroke-width=\"3\"/>';\n    }\n    $('groupChart').innerHTML = s;\n    $('roKept').textContent = grp.groups.length + ' 段断层';\n    $('roDropped').textContent = (grp.totalGroups - grp.groups.length) + ' 段碎段剔除';\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var faultBtns = $('faultBtns');\n    if (faultBtns) faultBtns.addEventListener('click', function (e) {\n      var b = e.target.closest('button'); if (!b) return;\n      segState.nFault = parseInt(b.dataset.faults, 10);\n      Array.prototype.forEach.call(faultBtns.querySelectorAll('button'), function (x) { x.classList.toggle('on', x === b); });\n      renderSeg(); renderSkel(); renderGroup();\n    });\n    var inWeight = $('inWeight');\n    if (inWeight) inWeight.addEventListener('input', function () {\n      segState.weight = parseFloat(inWeight.value);\n      $('outWeight').textContent = num(segState.weight, 2);\n      renderSeg(); renderSkel(); renderGroup();\n    });\n    var inThr = $('inThr');\n    if (inThr) inThr.addEventListener('input', function () {\n      skelThr = parseFloat(inThr.value);\n      $('outThr').textContent = num(skelThr, 2);\n      renderSeg(); renderSkel(); renderGroup();\n    });\n    var inMin = $('inMinLen');\n    if (inMin) inMin.addEventListener('input', function () {\n      grpState.minLen = parseInt(inMin.value, 10);\n      $('outMinLen').textContent = grpState.minLen;\n      renderGroup();\n    });\n  }\n\n  /* 抽屉上报（嵌入主站时按段落显示控件） */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '断层概率体', 'segCtl'], ['sec2', '断面骨架化', 'skelCtl'], ['sec3', '断层组合', 'grpCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      el.querySelectorAll('input, button').forEach(function (c) {\n        if (c.type === 'range') c.setAttribute('value', c.value);\n      });\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderSeg(); renderSkel(); renderGroup();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   地震断层自动解释 · 算法解剖（断层概率体 + 断面骨架化）\n   ---------------------------------------------------------\n   把「地震体 → 断层骨架」拆成 6 步，每一步都跑真代码：\n\n     ① 数据接入       振幅体 + 相干/曲率属性 + 对齐标签\n     ② 断层标签       历史解释断层转分割标签\n     ③ 断层概率体     3D U-Net 逐像素预测断层概率\n     ④ 类别不均衡     Dice / 焦点损失压住背景\n     ⑤ 断面骨架化     阈值 + 细化 → 断面中心线\n     ⑥ 断层组合       连通域 + 剔碎段 + 走向分组\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function ease(t) { return t * t * (3 - 2 * t); }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  /* 面板底部小结框 */\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* 振幅剖面着色 */\n  function ampColor(v) {\n    var t = clamp(v, -1, 1);\n    if (t >= 0) { var g = Math.round(220 * t); return 'rgb(' + g + ',' + g + ',' + (160 + 90 * t) + ')'; }\n    var b = Math.round(-220 * t); return 'rgb(' + (150 + 100 * b / 220) + ',' + b + ',' + b + ')';\n  }\n\n  /* 小格着色图 */\n  function cellMap(arr, W, H, cell, colorFn, x0, y0) {\n    var s = '';\n    for (var y = 0; y < H; y++) {\n      for (var x = 0; x < W; x++) {\n        var idx = y * W + x;\n        s += G.rect(x0 + x * cell, y0 + y * cell, cell, cell, { fill: colorFn(arr[idx]), op: 1 });\n      }\n    }\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nFault, L.weight, L.noise, L.thr, L.minLen].join(',');\n    if (cache.key === key) return cache;\n    var seis = M.genSeismic(64, 48, L.nFault, 20261105);\n    var prob = M.faultProb(seis, L.weight, L.noise);\n    var skel = M.skeletonFault(seis, prob.prob, L.thr, L.minLen);\n    var grp = M.faultGroup(seis, skel.pts, L.minLen);\n    cache = { key: key, L: L, seis: seis, prob: prob, skel: skel, grp: grp };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), seis = c.seis, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 振幅体', '断层处同相轴错断', C.jade);\n    s += G.panel(1, '② 相干属性', '断层响应更强', C.blue);\n    s += G.panel(2, '③ 对齐标签', '统一网格', C.clay);\n\n    var cell = 4, x0 = 30, y0 = 130;\n    /* 振幅剖面 */\n    s += cellMap(seis.amp, 64, 48, cell, ampColor, x0, y0);\n    /* 断层参考线 */\n    for (var f = 0; f < seis.faults.length; f++) {\n      var fl = seis.faults[f];\n      s += G.line(x0 + fl.x1 * cell, y0 + fl.y1 * cell, x0 + fl.x2 * cell, y0 + fl.y2 * cell, { stroke: '#f2c94c', sw: 1.6, dash: '6 3' });\n    }\n    s += G.txt(x0, y0 - 12, '三维地震振幅剖面（' + L.nFault + ' 条断层）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 相干属性示意：断层处更亮 */\n    var x1 = 330, y1 = 130;\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var idx = y * 64 + x;\n        var isF = seis.faultLabel[idx];\n        var v = isF ? 1 : 0.15 + Math.random() * 0.2;\n        s += G.rect(x1 + x * cell, y1 + y * cell, cell, cell, { fill: 'rgb(' + Math.round(120 + 130 * v) + ',' + Math.round(90 + 100 * v) + ',' + Math.round(80 + 60 * v) + ')', op: 1 });\n      }\n    }\n    s += G.txt(x1, y1 - 12, '相干属性（断层处高响应）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(30, 570, 130, 128, '为什么加属性通道',\n      ['· 振幅剖面里断层是「同相轴错断」',\n       '· 相干/曲率属性放大断层不连续',\n       '· 多通道输入增强断层判别',\n       '· 与历史断层标签统一网格对齐'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '属性计算相位畸变会让模型学到「假象」而非断层', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '工区', v: '200 km²' }, { k: '断层条数', v: L.nFault + ' 条' }, { k: '通道', v: '振幅+属性' }], note: '第一步先把地下断层\"看清楚\"：振幅剖面里断层是错断的同相轴，相干/曲率属性把它放大，为分割做准备。' };\n  }\n\n  /* =========================================================\n     ② 断层标签\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), seis = c.seis, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 历史断层', '量大但带分歧', C.clay);\n    s += G.panel(1, '② 标签清洗', '合并分歧·剔噪声', C.jade);\n    s += G.panel(2, '③ 断层标签', '体素级真值', C.blue);\n\n    var cell = 4, x0 = 30, y0 = 130;\n    /* 断层真值标签 */\n    s += cellMap(seis.faultLabel, 64, 48, cell, function (v) { return v ? '#2f7d6b' : '#f4f3ef'; }, x0, y0);\n    s += G.txt(x0, y0 - 12, '断层分割标签（断层像素' + ' <1%）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 历史标签带分歧（边界抖动） */\n    var rnd = M.mulberry32(20261107);\n    var x1 = 330, y1 = 130;\n    for (var y = 0; y < 48; y++) {\n      for (var x = 0; x < 64; x++) {\n        var idx = y * 64 + x;\n        var v = seis.faultLabel[idx];\n        if (v && rnd() < 0.25) v = 0;\n        s += G.rect(x1 + x * cell, y1 + y * cell, cell, cell, { fill: v ? '#b26a39' : '#f4f3ef', op: 1 });\n      }\n    }\n    s += G.txt(x1, y1 - 12, '历史标签（带解释员分歧）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(30, 570, 130, 128, '标签策略',\n      ['· 历史解释断层体素化即标签',\n       '· 量大但含解释员分歧（噪声）',\n       '· 清洗：合并分歧、剔非断层噪声',\n       '· 少量精修标签拉精度上限'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '断层标签稀缺：历史断层量大但脏，必须清洗后再训练', { size: 9, fill: '#8a4f27' });\n    return { svg: s, stats: [{ k: '标签来源', v: '历史断层' }, { k: '标签量', v: '5—10 工区' }, { k: '策略', v: '清洗+精修' }], note: '历史解释断层直接体素化成标签弥补稀缺，但带解释员分歧；清洗合并分歧、剔除非断层噪声，再用少量精修标签校准。' };\n  }\n\n  /* =========================================================\n     ③ 断层概率体\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), seis = c.seis, prob = c.prob, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 编码器', '下采样提特征', C.blue);\n    s += G.panel(1, '② 解码器', '上采样回分辨率', C.jade);\n    s += G.panel(2, '③ 断层概率', '每像素一个概率', C.clay);\n\n    var x0 = 30, y0 = 130, w = 540, h = 130;\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 2 });\n    /* 3D U-Net 收缩-扩张 */\n    var steps = Math.floor(t * 5);\n    var levelW = [110, 86, 62, 42, 62, 86, 110];\n    var levelY = [y0 + 18, y0 + 42, y0 + 58, y0 + 66, y0 + 58, y0 + 42, y0 + 18];\n    for (var i = 0; i <= steps && i < 7; i++) {\n      var filled = (i === steps);\n      var lx = x0 + 30 + i * 74;\n      s += G.rect(lx, levelY[i], levelW[i], 40, { r: 6, fill: filled ? (i < 3 ? C.blueL : C.jadeL) : '#f4f3ef', stroke: i < 3 ? '#9fb5cf' : '#a7c6b8' });\n      s += G.txt(lx + levelW[i] / 2, levelY[i] + 24, i < 3 ? '↓ 下采样' : '↑ 上采样', { size: 8, fill: C.ink3, anchor: 'middle' });\n    }\n    s += G.txt(x0, y0 - 12, '3D U-Net：地震体 → 断层概率体（每像素一个断层概率）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    /* 右：概率体缩略 */\n    var cell = 3, rx = 30 + 40, ry = y0 + 140;\n    for (var y = 0; y < 48; y += 1) {\n      for (var x = 0; x < 64; x += 1) {\n        var idx = y * 64 + x;\n        var p = prob.prob[idx];\n        var g = Math.round(255 * p);\n        s += G.rect(rx + x, ry + y, 1, 1, { fill: 'rgb(' + g + ',' + g + ',130)', op: 1 });\n      }\n    }\n    s += G.txt(rx, ry - 8, '断层概率体', { size: 8.5, fill: C.ink3, anchor: 'middle' });\n    s += G.txt(rx, ry + 56, '断层处概率高 · 背景干净', { size: 8.5, fill: C.ink3 });\n\n    return { svg: s, stats: [{ k: '模型', v: '3D U-Net' }, { k: '输出', v: '断层概率体' }, { k: '损失', v: 'Dice/焦点' }], note: '3D U-Net 在整块地震体上逐像素预测断层概率。断层像素占比<1%，必须用焦点 / Dice 损失压住背景，否则模型全判非断层。' };\n  }\n\n  /* =========================================================\n     ④ 类别不均衡\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), seis = c.seis, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 断层像素', '占比 <1%', C.jade);\n    s += G.panel(1, '② 普通损失', '偏向背景', C.clay);\n    s += G.panel(2, '③ 焦点/Dice', '抓住稀疏断层', C.blue);\n\n    var x0 = 30, y0 = 130;\n    /* 断层 vs 背景占比 */\n    var gt = 0, n = 64 * 48;\n    for (var i = 0; i < n; i++) gt += seis.faultLabel[i];\n    var ratio = gt / n;\n    s += G.txt(x0, y0 - 12, '断层像素占比 ' + f(ratio * 100, 1) + '%（类别极不均衡）', { size: 9.5, fill: C.ink2, weight: 700 });\n    /* 占比条 */\n    s += G.rect(x0, y0, 540, 34, { r: 6, fill: '#f4f3ef' });\n    s += G.rect(x0, y0, 540 * ratio, 34, { r: 6, fill: '#2f7d6b' });\n    s += G.txt(x0 + 12, y0 + 23, '断层 ' + f(ratio * 100, 1) + '%', { size: 9, fill: '#fff', weight: 700 });\n    s += G.txt(x0 + 540 * ratio + 12, y0 + 23, '背景 ' + f((1 - ratio) * 100, 1) + '%', { size: 9, fill: C.ink2 });\n\n    s += footBox(x0, 570, 200, 176, '为什么普通损失会翻车',\n      ['· 全判成背景也能拿到 99%+ 准确率',\n       '· 但小断层一条都抓不到',\n       '· 焦点损失：压低易分类样本权重',\n       '· Dice 损失：直接优化区域重叠',\n       '',\n       '目标：Dice ≥ 0.6 · 检出率 ≥ 0.9',\n       '小断层一条都不能漏'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '类别不均衡是断层分割头号陷阱：普通交叉熵全判背景却\"准确率很高\"', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '断层占比', v: f(ratio * 100, 1) + '%' }, { k: '损失', v: '焦点/Dice' }, { k: '目标', v: '检出率≥0.9' }], note: '断层像素占比<1%是最容易翻车的点：普通交叉熵把所有像素判成背景也能拿到高准确率，但小断层一条都抓不到，必须用焦点 / Dice 损失。' };\n  }\n\n  /* =========================================================\n     ⑤ 断面骨架化\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), seis = c.seis, prob = c.prob, skel = c.skel, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 断层概率', '断层处概率高', C.jade);\n    s += G.panel(1, '② 阈值切割', '>thr 判为断层', C.blue);\n    s += G.panel(2, '③ 断面骨架', '细长中心线', C.clay);\n\n    var x0 = 30, y0 = 130, cell = 4;\n    var W = 64, H = 48;\n    /* 断层概率底图 */\n    s += cellMap(prob.prob, 64, 48, cell, function (v) { var g = Math.round(255 * v); return 'rgb(' + g + ',' + g + ',130)'; }, x0, y0);\n    /* 骨架像素 */\n    for (var pi = 0; pi < skel.pts.length; pi++) {\n      var p = skel.pts[pi];\n      s += G.rect(x0 + p.x * cell + 1, y0 + p.y * cell + 1, cell - 2, cell - 2, { fill: '#b05a51', op: 1 });\n    }\n    /* 真实断层线 */\n    for (var fi = 0; fi < seis.faults.length; fi++) {\n      var fl = seis.faults[fi];\n      s += G.line(x0 + fl.x1 * cell, y0 + fl.y1 * cell, x0 + fl.x2 * cell, y0 + fl.y2 * cell, { stroke: '#2f7d6b', sw: 2, dash: '6 3' });\n    }\n    s += G.txt(x0, y0 - 12, '断面骨架化 · 阈值 ' + f(L.thr, 2) + ' · ' + skel.pts.length + ' 个骨架像素', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(320, 270, 130, 192, '断层为什么难提',\n      ['· 断层细长、低对比',\n       '→ 直接阈值会断断续续',\n       '· 需要细化提取中心线',\n       '· 形态学连接补断点',\n       '· 走向约束顺延断层',\n       '',\n       '细长低对比目标最易漏判，',\n       '骨架化是把\"一片概率\"提纯成\"一条线\"。'], 'clay');\n\n    s += G.txt(x0, y0 + 208, '红色 = 骨架中心线 · 绿色虚线 = 真实断层参考', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '骨架像素', v: skel.pts.length }, { k: '阈值', v: f(L.thr, 2) }], note: '断层是细长的低对比目标：从概率体阈值得到一片断层带，再用细化提取中心线成断面骨架。阈值太低噪声多、太高断断续续，需要走向约束与形态学连接。' };\n  }\n\n  /* =========================================================\n     ⑥ 断层组合\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), grp = c.grp, seis = c.seis, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 连通域', '断层像素连成段', C.blue);\n    s += G.panel(1, '② 剔碎段', '长度不足剔除', C.clay);\n    s += G.panel(2, '③ 断层组合', '按走向分组', C.jade);\n\n    var x0 = 30, y0 = 130, cell = 4;\n    /* 断层概率底图 */\n    s += cellMap(seis.faultLabel, 64, 48, cell, function (v) { return v ? '#2f7d6b' : '#f4f3ef'; }, x0, y0);\n    /* 分组后的断层段 */\n    for (var gi = 0; gi < grp.groups.length; gi++) {\n      var g = grp.groups[gi];\n      s += G.line(x0 + g.x * cell + 2, y0 + g.y0 * cell + 2, x0 + g.x * cell + 2, y0 + g.y1 * cell + 2, { stroke: '#b26a39', sw: 3 });\n    }\n    s += G.txt(x0, y0 - 12, '断层组合 · 保留 ' + grp.groups.length + ' 段 · 剔除 ' + (grp.totalGroups - grp.groups.length) + ' 段碎段', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(320, 270, 130, 192, '为什么后处理',\n      ['· 骨架像素是一堆点，不成\"断层\"',\n       '· 连通域：沿走向连成一段段断层',\n       '· 剔碎段：长度不足的噪声删掉',\n       '· 走向分组：形成可追踪的断层组合',\n       '',\n       '过度连接 → 相邻独立小断层并成一条',\n       '碎段不剔 → 组合全是噪声短线。'], 'jade');\n\n    s += G.txt(x0, y0 + 208, '产出：断层骨架 + 走向 + 置信度字段 → 直接用于构造建模', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '断层段', v: grp.groups.length }, { k: '剔碎段', v: grp.totalGroups - grp.groups.length }], note: '骨架像素要变成可入库的断层组合，必须做连通域、剔碎段、按走向分组三步后处理。过度连接并掉独立小断层，碎段不剔除又全是噪声短线。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：地震断层自动解释<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n/* 右侧控件抽屉（嵌入主站时由父页面接管，这里保留独立样式兜底） */\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 物探解释 / 地震断层自动解释<\/span>\n  <h1>从「逐剖面人工追踪 2—4 周」到「断层概率体 · 天级出断面骨架」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂断层概率体预测、Q2 断面骨架化、Q3 断层组合后处理。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 断层解释全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「地震体 → 黑盒 → 断层图」，而是<b>逐段展开<\/b>：数据接入 → 断层标签 → 概率体 → 类别不均衡 → 骨架化 → 断层组合，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 3—5<\/span>\n    <h2>把「地震体 → 断层骨架」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改断层条数、分割权重、骨架阈值和最小延伸长度，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（断层概率、骨架像素、断层组合）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>faultProb / skeletonFault / faultGroup<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 3 步用 3D U-Net 编码器-解码器结构示意「整块体逐像素预测断层概率」；<b>②<\/b> 第 4 步专门放大断层像素占比，看得见「类别不均衡为什么最容易翻车」。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 断层概率体 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">逐剖面人工追踪 2—4 周/数据体；三维语义分割把全数据体压到天级<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 3<\/span>\n    <h2>断层概率体：每个像素到底是不是断层<\/h2>\n    <p class=\"leadline\">切断层条数、拖分割权重、调骨架阈值，看断层概率体与分割结果的差距——这就是「整块地震体逐像素判别断层」的核心。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"segCtl\">\n    <div class=\"btns\" id=\"faultBtns\">\n      <button type=\"button\" data-faults=\"2\">2 条断层<\/button>\n      <button type=\"button\" data-faults=\"3\" class=\"on\">3 条断层<\/button>\n      <button type=\"button\" data-faults=\"5\">5 条断层<\/button>\n    <\/div>\n    <div class=\"sl\">\n      <label>分割权重<output id=\"outWeight\">0.60<\/output><\/label>\n      <input type=\"range\" id=\"inWeight\" min=\"0\" max=\"1.4\" step=\"0.05\" value=\"0.6\">\n    <\/div>\n  <\/div>\n  <div class=\"fg\">\n    <div><svg id=\"seisAmp\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"地震振幅剖面\"><\/svg><div class=\"cap\">地震振幅剖面（黄虚线 = 真断层）<\/div><\/div>\n    <div><svg id=\"faultProb\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"断层概率体\"><\/svg><div class=\"cap\">断层概率体（越亮越可能是断层）<\/div><\/div>\n  <\/div>\n  <svg id=\"faultSeg\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"断层分割结果\" style=\"margin-top:12px\"><\/svg>\n  <div class=\"rrow ro1\">\n    <div class=\"ro\"><span class=\"k\">断层像素召回率<\/span><b id=\"roRecall\" class=\"good\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"segTip\">拖「分割权重」模拟模型训练充分程度：权重越高，断层处概率越准、背景越干净。断层像素占比常低于 1%，权重低时小断层最容易被背景吞掉。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 断面骨架化 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>阈值切割<\/b> + <b>细化骨架<\/b> 从断层概率里提取细长的断面中心线<span class=\"qa-algo\">计算机视觉 · 三维语义分割 / 骨架化<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>断面骨架：从一片断层概率里「捞」出一条线<\/h2>\n    <p class=\"leadline\">断层细长、低对比，直接阈值会断断续续。拖阈值在「检出更多」与「噪声更少」之间取平衡。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"skelCtl\">\n    <div class=\"sl\">\n      <label>骨架阈值<output id=\"outThr\">0.50<\/output><\/label>\n      <input type=\"range\" id=\"inThr\" min=\"0.2\" max=\"0.9\" step=\"0.02\" value=\"0.5\">\n    <\/div>\n  <\/div>\n  <svg id=\"skelChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"断层概率与断面骨架化\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">骨架像素<\/span><b id=\"roSkelPts\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">阈值<\/span><b id=\"roThr\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"skelTip\">红色 = 断面的骨架中心线，绿色虚线 = 真实断层参考。阈值低：断层全出来但噪声多；阈值高：干净但断面断断续续。骨架化把「一片概率」提纯成「一条线」。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 断层组合 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">断层像素 → 连通域 → 剔碎段 → 按走向分组 → 可直接用于构造建模的断层组合<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5<\/span>\n    <h2>断层组合：像素怎么变成「可追踪的断层段」<\/h2>\n    <p class=\"leadline\">把断层骨架沿走向连成段，剔除长度不足的碎段，得到带走向与置信度的断层组合——这才是能入库构造建模的成果。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"grpCtl\">\n    <div class=\"sl\">\n      <label>最小延伸长度<output id=\"outMinLen\">8<\/output><\/label>\n      <input type=\"range\" id=\"inMinLen\" min=\"2\" max=\"20\" step=\"1\" value=\"8\">\n    <\/div>\n  <\/div>\n  <svg id=\"groupChart\" viewBox=\"0 0 512 384\" role=\"img\" aria-label=\"断层组合后处理结果\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">保留断层段<\/span><b id=\"roKept\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">剔除碎段<\/span><b id=\"roDropped\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"grpTip\">橙色 = 保留的断层段。最小延伸长度太小：噪声短线也被保留；太大：有价值的短断层被并掉或删掉。后处理的质量决定断层组合能不能直接用。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 3<\/b><br>3D U-Net 逐像素预测断层概率体。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>阈值 + 细化，从概率体提取断面骨架。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>连通域 + 剔碎段 + 走向分组 → 断层组合。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：地震剖面由「层位 + 断层错断 + 噪声」合成，断层真值已知、仅供对比；断层概率预测、断面骨架化与断层组合均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：一个地震体怎么一步步变成断层骨架',\n    stages: [\n      { name: '数据接入', tag: '振幅+属性', dur: 4200, draw: function (t, g) { return F.stage1(t); } },\n      { name: '断层标签', tag: '历史转标签', dur: 4400, draw: function (t, g) { return F.stage2(t); } },\n      { name: '断层概率体', tag: '3D U-Net', dur: 4800, draw: function (t, g) { return F.stage3(t); } },\n      { name: '类别不均衡', tag: 'Dice/焦点损失', dur: 4400, draw: function (t, g) { return F.stage4(t); } },\n      { name: '断面骨架化', tag: '阈值+细化', dur: 4600, draw: function (t, g) { return F.stage5(t); } },\n      { name: '断层组合', tag: '连通域+剔碎段', dur: 4600, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的地震剖面演示断层概率体预测、断面骨架化与断层组合后处理。","height":600};
  var META = {"id":"s1-fault-interp","sceneId":"s1","title":"地震断层自动解释：三维语义分割与断面骨架化"};
  var handle = null;
  var DEF = {"id":"s1-fault-interp","sceneId":"s1","title":"地震断层自动解释：三维语义分割与断面骨架化","methods":["cv"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"三维地震体","desc":"200 km² 级，SEG-Y 数十 GB"},{"label":"标注成本","value":"高","desc":"断层像素占比常低于 1%，标签稀缺"},{"label":"可见收益","value":"2—4 周 → 天级","desc":"全数据体解释时间大幅压缩"},{"label":"难度","value":"高","desc":"断层像素占比低、标签稀缺、跨工区迁移困难"}],"lede":"三维地震数据体是构造解释的基础——解释员要在上千个 inline 剖面上逐条追踪断面，形成断层骨架，再用于构造建模与井位部署。智能方法把「逐剖面人工追踪」升级为「三维语义分割」：用一个 3D 卷积网络在整块数据体上预测每个像素属于断层的概率，再骨架化提取断面，人工只做质检与修正。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>构造解释的第一步是把地下<b>「断层」看清楚<\/b>：解释员在三维地震数据体的上千个 inline / crossline 剖面上，逐条追踪断层被错断的同相轴，形成断层骨架，再用于构造建模与井位部署。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>慢<\/b>——一个 200 km² 数据体全人工解释需 <b>2—4 周<\/b>，逐剖面逐条追踪<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>不一致<\/b>——不同解释员对同一断层的组合常有分歧，成果难以复用<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>易漏小断层<\/b>——深层信噪比低处小断层易漏，而小断层常控制油气运移与圈闭<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工断层解释的慢、不一致与易漏\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">人工断层解释：慢 · 不一致 · 易漏小断层<\/text><rect x=\"20\" y=\"36\" width=\"186\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"113\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">一个数据体 × 上千剖面<\/text><rect x=\"36\" y=\"70\" width=\"60\" height=\"90\" rx=\"4\" fill=\"#dce6e6\" stroke=\"#9fb5cf\" stroke-dasharray=\"4 2\"/><rect x=\"96\" y=\"70\" width=\"94\" height=\"90\" rx=\"4\" fill=\"#dce6d6\" stroke=\"#9fb58f\" stroke-dasharray=\"4 2\"/><path d=\"M36 90 L96 160\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/><text x=\"113\" y=\"178\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a6b52\">断层 A<\/text><rect x=\"36\" y=\"196\" width=\"60\" height=\"6\" rx=\"3\" fill=\"#dce6e6\"/><rect x=\"96\" y=\"196\" width=\"94\" height=\"6\" rx=\"3\" fill=\"#dce6d6\"/><text x=\"233\" y=\"66\" font-size=\"10\" fill=\"#4d565b\">逐剖面追踪<\/text><text x=\"233\" y=\"80\" font-size=\"13\" fill=\"#b26a39\" font-weight=\"700\">2—4 周<\/text><text x=\"233\" y=\"98\" font-size=\"9.5\" fill=\"#79828a\">上千个 inline 剖面<\/text><text x=\"233\" y=\"150\" font-size=\"10\" fill=\"#4d565b\">断层组合有分歧<\/text><text x=\"233\" y=\"164\" font-size=\"10\" fill=\"#4d565b\">深层小断层<\/text><text x=\"233\" y=\"178\" font-size=\"10\" fill=\"#b26a39\" font-weight=\"700\">易漏判<\/text><text x=\"233\" y=\"198\" font-size=\"9.5\" fill=\"#79828a\">但控制油气运移<\/text><path d=\"M222 126 C232 130 240 138 246 150\" fill=\"none\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><rect x=\"270\" y=\"36\" width=\"330\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"435\" y=\"58\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">深层低信噪比区：小断层易漏<\/text><path d=\"M300 150 C320 138 340 148 360 140 C380 132 400 144 420 138\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"3\" opacity=\"0.7\"/><path d=\"M310 168 C330 158 350 166 370 158\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.5\" opacity=\"0.6\"/><text x=\"300\" y=\"130\" font-size=\"9\" fill=\"#5a6a7a\">噪声层<\/text><rect x=\"440\" y=\"120\" width=\"140\" height=\"70\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#d8a48c\" stroke-dasharray=\"5 3\"/><text x=\"510\" y=\"142\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">小断层（易漏判）<\/text><text x=\"510\" y=\"158\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">被噪声掩盖<\/text><text x=\"510\" y=\"172\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a6b52\">人工难以分辨<\/text><text x=\"300\" y=\"206\" font-size=\"8.5\" fill=\"#8a6b52\">深层小断层最容易被忽略<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「逐剖面人工追踪」换成「<b>三维语义分割<\/b>」：一个 3D 卷积网络在整块地震体上为每个像素预测断层概率，再经<b>骨架化<\/b>提取断面骨架，解释员只做质检与修正。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>断层概率体<\/b>——3D U-Net 逐像素预测断层概率，断层像素占比虽低于 1% 也能被抓住<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>断面骨架化<\/b>——对概率体做细化与连接，提取断面骨架，形成断层组合<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>类别不均衡 + 弱监督<\/b>——断层像素极稀疏，用焦点损失与相干/曲率属性增强，缓解标签稀缺<\/span><\/div><\/div><p>落地形态：全数据体解释从 2—4 周压到天级；算法输出一致、可量化的断层骨架，解释员把精力放在疑点断层与深层低信噪比区。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"三维断层语义分割流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">三维语义分割：地震体 → 断层概率体 → 断面骨架<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">三维地震体<\/text><rect x=\"32\" y=\"72\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#8aa7a7\"/><rect x=\"70\" y=\"72\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#cbbf9a\"/><path d=\"M32 74 L106 108\" stroke=\"#b26a39\" stroke-width=\"2.5\"/><rect x=\"32\" y=\"110\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#9b86a8\"/><rect x=\"70\" y=\"110\" width=\"36\" height=\"36\" rx=\"3\" fill=\"#a8bfd4\"/><text x=\"80\" y=\"178\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">SEG-Y · 数十 GB<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">3D U-Net<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">三维卷积网络<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">逐像素预测断层<\/text><text x=\"237\" y=\"134\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">断层像素占比 <1%<\/text><text x=\"237\" y=\"150\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">焦点损失 + 属性增强<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"394\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">断层概率体<\/text><text x=\"394\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">概率骨架化<\/text><text x=\"394\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">提取断面骨架<\/text><text x=\"394\" y=\"118\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">形成断层组合<\/text><path d=\"M458 100 L482 100\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"486\" y=\"40\" width=\"114\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"543\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">解释员复核<\/text><text x=\"543\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">质检 + 修正<\/text><text x=\"543\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">疑点断层复查<\/text><text x=\"543\" y=\"118\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">深层低信噪比区<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">产出一致、可量化的断层骨架 → 直接用于构造建模<\/text><text x=\"310\" y=\"226\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">人不再逐剖面追踪，只处理算法拿不准的疑点断层<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>三维地震振幅体<\/b>：200 km² 级、SEG-Y 数十 GB，是断层分割的主信号；<b>相干 / 曲率等属性体<\/b>：与振幅体同网格，可由振幅体自动生成，作为辅助通道增强断层判别；<b>历史解释断层<\/b>：已有解释成果的工区直接转为<b>断层标签<\/b>，弥补标签稀缺；<b>F3 Netherlands 等公开数据体<\/b>：含断层解释，可作起步与跨工区预训练。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">四类数据 + 标签策略<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">三维地震振幅体<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">200 km² 级 · SEG-Y 数十 GB · 主信号<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">断层像素占比常低于 1%<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">相干 / 曲率属性体<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">与振幅体同网格 · 辅助通道<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">由振幅体自动生成 · 增强断层响应<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">历史解释断层<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">已有解释成果的工区 · 直接转标签<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">量大但需清洗，含解释员分歧<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">F3 等公开数据体<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">含断层解释 · 可跨工区预训练<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">降低起步门槛<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">标签策略：历史断层（量大）+ 相干/曲率属性增强 → 缓解「断层标签稀缺」<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>类别极不均衡<\/b>——断层像素占比常低于 1%，普通交叉熵会全部预测成「非断层」<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>标签稀缺且带分歧<\/b>——断层标注昂贵，不同解释员的断层组合不一致，标签本身有噪声<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>跨工区迁移困难<\/b>——不同工区的频率、信噪比差异大，换区容易掉精度<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>公开数据体（F3）+ 焦点损失 / Dice 损失<\/b>把基线做出来，压住类别不均衡；再加<b>相干 / 曲率属性通道<\/b>增强断层响应；最后做<b>跨工区预训练 + 少量微调<\/b>与<b>解释员在环<\/b>，用新区少量断层标签持续校准。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 类别极不均衡<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">断层像素占比 <1%，易全判非断层<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">焦点损失 / Dice 损失<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">压住背景，抓住稀疏断层<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 标签稀缺 + 分歧<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">断层标注贵、解释员有分歧<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">相干/曲率属性增强<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">多通道输入增强断层响应<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 跨工区迁移差<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">频率 / 信噪比差异导致迁移困难<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">跨区预训练 + 人在环<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">新区少量断层标签持续校准<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">焦点损失基线 → 属性增强 → 跨区预训练 + 人在环<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一个工区的三维断层自动解释改造","lead":["某工区 200 km² 三维地震体，此前全人工断层解释需 2—4 周、断层组合与解释员分歧大。目标：用 3D 卷积语义分割把全数据体解释压到天级，输出一致的断层骨架，深层小断层也能被抓住。","注意第 3、4、5 步：断层概率预测、断面骨架化、断层组合是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["工区","200 km²"],["数据体","SEG-Y 数十 GB"],["断层像素占比","<1%"],["解释断层","5—10 工区"],["目标时间","天级"],["深层小断层","不漏判"]],"steps":[{"name":"数据接入与属性增强","role":"数据","do":"三维地震振幅体读入、重采样到统一网格；用相干 / 曲率等属性体作为辅助通道；与历史解释断层对齐。示范页屏 1 顶部可切换振幅 / 相干属性看断层对比度差异。","effect":"一张与历史断层标签严格对齐的多通道地震体，作为分割输入。","trap":"重采样与属性计算引入的相位畸变会模糊断层响应，模型学到「假象」而非「断层」。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：重采样 → 属性增强 → 对齐<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"44\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">地震振幅体<\/text><text x=\"99\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">SEG-Y · 数十 GB<\/text><path d=\"M178 64 L202 64\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"44\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"281\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">相干/曲率属性<\/text><text x=\"281\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">辅助通道增强<\/text><path d=\"M360 64 L384 64\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"200\" height=\"44\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"488\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">对齐历史断层标签<\/text><text x=\"488\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">统一网格<\/text><text x=\"24\" y=\"112\" font-size=\"9\" fill=\"#79828a\">· 振幅 + 相干 + 曲率多通道 · 断层在相干属性里响应更强<\/text><text x=\"24\" y=\"130\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：属性计算相位畸变 → 模型学到「假象」而非「断层」<\/text><\/svg>"},{"name":"断层标签构建","role":"标注","do":"历史解释断层按体素语义转成分割标签；对标签做清洗（合并解释员分歧、剔除非断层噪声）。按工区切块、留出独立验证体。示范页屏 1 顶部可对比不同工区的断层标签密度。","effect":"有可训练、可复现评测的断层标签集，弥补「断层标签稀缺」。","trap":"历史标签带解释员分歧，直接把分歧噪声学进模型，边界会偏移到某个人手边。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">标签构建：历史断层转标签 + 清洗 + 切块<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">历史解释断层<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">体素转标签 · 量大<\/text><path d=\"M188 68 L210 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">标签清洗<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">合并分歧·剔噪声<\/text><path d=\"M378 68 L400 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">切块 + 独立验证体<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按工区留出评测口径<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：历史标签带解释员分歧 → 把分歧噪声学进模型 → 边界偏移<\/text><\/svg>"},{"name":"断层概率体预测","role":"算法核心","do":"用 3D U-Net 在整块地震体上逐像素预测断层概率；损失用焦点 / Dice 损失缓解类别不均衡；历史标签与少量精修标签混合训练。示范页屏 1 在浏览器里实时跑一个小型断层分割演示。","effect":"输出每像素的断层概率体，直接能看到整块体里的断层分布。","trap":"类别不均衡下模型偏向背景，断层像素占比 <1% 时最易被全部吞掉。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">断层概率体：3D U-Net 逐像素预测<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">地震 Patch<\/text><rect x=\"38\" y=\"72\" width=\"30\" height=\"30\" rx=\"2\" fill=\"#8aa7a7\"/><rect x=\"70\" y=\"72\" width=\"30\" height=\"30\" rx=\"2\" fill=\"#cbbf9a\"/><path d=\"M170 77 L200 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"204\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"269\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">3D 编码器-解码器<\/text><text x=\"269\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">3D U-Net<\/text><text x=\"269\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">Dice / 焦点损失<\/text><path d=\"M338 77 L368 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"372\" y=\"42\" width=\"200\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"472\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">断层概率体<\/text><text x=\"472\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每像素一个断层概率<\/text><text x=\"472\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">阈值 >thr 判为断层<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：类别不均衡 → 模型偏向背景，断层像素占比<1%时最易被吞掉<\/text><\/svg>"},{"name":"断面骨架化","role":"算法核心","do":"从断层概率体里提取断面骨架：对概率体做细化（骨架化）与连接，得到细长的断层中心线；按断层走向与延伸长度统计。示范页屏 2 展示从概率体到断面骨架的细化过程。","effect":"把「一片断层概率」提纯成「一条断面骨架」，变成可追踪的线状要素。","trap":"断层是细长低对比目标，直接阈值会断断续续，需要形态学连接与走向约束。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">断面骨架化：概率体 → 细化 → 连接 → 骨架<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">断层概率体<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">断层处概率高<\/text><path d=\"M178 77 L202 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">细化骨架<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">提取中心线<\/text><path d=\"M360 77 L384 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"150\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"463\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">连接 + 走向约束<\/text><text x=\"463\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">补断点、顺走向<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：断层细长低对比 → 阈值法断断续续，需形态学连接 + 走向约束<\/text><\/svg>"},{"name":"断层组合与后处理","role":"工程环节","do":"对骨架做连通域分析、剔碎段、按走向分组；断层骨架输出为可量化的断层组合（带置信度字段）。示范页屏 3 展示骨架化前后与按走向分层的断层清单。","effect":"干净、可直接用于构造建模的断层骨架组合，而非散乱的概率像素。","trap":"过度连接把相邻的独立小断层并成一条；碎段不剔除会让断层组合全是噪声短线。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">后处理：连通域 → 分组 → 剔碎段 → 断层组合<\/text><rect x=\"24\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"89\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">断面骨架<\/text><text x=\"89\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">含碎段<\/text><path d=\"M158 77 L182 77\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"186\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"251\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">连通域 + 分组<\/text><text x=\"251\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按走向分组<\/text><path d=\"M320 77 L344 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"348\" y=\"42\" width=\"130\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"413\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">剔碎段<\/text><text x=\"413\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">滤掉噪声短线<\/text><path d=\"M482 77 L506 77\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"510\" y=\"42\" width=\"86\" height=\"70\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"553\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">断层组合<\/text><text x=\"553\" y=\"78\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">带置信度<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：过度连接并掉独立小断层；碎段不剔除 → 断层组合全是噪声短线<\/text><\/svg>"},{"name":"人工复核与构造建模","role":"人工确认","do":"解释员对置信度低、疑点断层与深层低信噪比区抽查复核，局部修正后确认；断层骨架进入构造建模与井位部署；错误反馈回训练集。示范页屏 3 展示按置信度分层的复核清单。","effect":"人只处理算法拿不准的地方，断层组合可信、可追溯，错误持续回流改进模型。","trap":"没有人在环，算法错判的断层直接进入构造建模，会在下游井位部署里扩散。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">人工复核：按置信度分层 → 局部修正 → 回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">置信度分层<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">高置信自动通过<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">人工复核修正<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">疑点·深层低信噪比区<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">构造建模 + 回流<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">井位部署 + 错误回流<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：无人在环 → 算法错判断层直接进构造建模 → 井位部署扩散<\/text><\/svg>"}],"metrics":{"title":"怎么算「断层解释对了」","html":"<p>断层语义分割用 <b>Dice / IoU<\/b> 与 <b>断层检出率<\/b> 双重验收：Dice 反映断层区域命中，检出率反映「该抓的断层抓没抓到」——<b>类别不均衡下 IoU 可能被背景拉高，但小断层一条没抓到<\/b>。<\/p><p>断面骨架单独算 <b>骨架连通性<\/b>（断面是否连续、有无断裂）与 <b>走向一致性<\/b>；最终还要与人工解释比<b>全数据体时间<\/b>与<b>断层组合分歧度<\/b>。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='断层解释效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>断层解释验收：Dice 与检出率并重<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>断层区域命中<\/text><rect x='34' y='66' width='70' height='44' rx='4' fill='#d8a48c' opacity='0.6'/><path d='M34 66 C50 76 70 86 104 88 C118 88 128 92 154 96' fill='none' stroke='#2f7d6b' stroke-width='2.5'/><text x='170' y='86' font-size='9' fill='#4d565b'>检出率<\/text><text x='170' y='102' font-size='9' fill='#b26a39' font-weight='700'>小断层不漏<\/text><text x='170' y='120' font-size='8.5' fill='#79828a'>Dice ≥ 0.6 · 检出率 ≥ 0.9<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>类别不均衡下 IoU 可能被背景拉高，但小断层一条没抓到<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>与人工解释比全数据体时间<\/text><rect x='340' y='66' width='90' height='52' fill='#d9b78e'/><text x='385' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>2—4 周<\/text><text x='385' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>人工解释<\/text><rect x='500' y='66' width='90' height='52' fill='#2f7d6b'/><text x='545' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>天级<\/text><text x='545' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>AI 分割<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>时间压缩 + 断层组合一致性统一<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 断层 Dice × 检出率 × 全数据体时间 · 小断层一条都不能漏<\/text><\/svg><\/p>"},"fails":[{"name":"类别不均衡吞掉断层","why":"断层像素占比常低于 1%，普通交叉熵把全部像素判成非断层，小断层一条都抓不到。"},{"name":"标签带解释员分歧","why":"历史断层标签来自不同解释员，边界不一致，模型学到的是某个人手边的偏移而非断层本身。"},{"name":"跨工区迁移掉精度","why":"不同工区的频率、信噪比差异大，换一个工区直接掉精度，需跨区预训练与少量微调。"},{"name":"过度连接并掉小断层","why":"骨架化 / 后处理过度连接把相邻的独立小断层并成一条，或碎段不剔除让组合全是噪声短线。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的地震剖面演示断层概率体预测、断面骨架化与断层组合后处理。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
